'use strict';
const $=s=>document.querySelector(s), KEY='seven-good-adm-v1', DAILY_RIDES=2;
let state={version:1,people:[],records:{}}, selected=null, tab='vt', editing=null, paymentContext=null, activeWeekIndex=null, activeWeekMonth=null;
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved));}catch{alert('Não foi possível carregar os dados salvos. Preserve seu backup antes de fazer alterações.');}
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(Number(v))&&Number(v)>=0?Number(v):0;
const cents=n=>Math.round(num(n)*100);
const initialMonth=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).format(new Date());
$('#month').value=initialMonth;
seedRentDetails();
seedMarketing();
seedServiceHours();
if(!state.teamSeeded){for(const [id,name] of [['lucas-gargi','Lucas Gargi'],['atila-carvalho','Átila Carvalho'],['emanuel-vieira','Emanuel Vieira'],['douglas','Douglas'],['meire','Meire']]){if(!state.people.some(p=>p.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))state.people.push({id:'seven-'+id,name,role:'Vendedor',pixType:'CPF',pix:''});}state.teamSeeded=true;}
if(!state.luizBorgesSeeded){if(!state.people.some(p=>p.id==='seven-luiz-borges'||p.name.trim().toLocaleLowerCase('pt-BR')==='luiz borges'))state.people.push({id:'seven-luiz-borges',name:'Luiz Borges',role:'Vendedor',pixType:'CPF',pix:''});state.luizBorgesSeeded=true;}
function syncScreenshotTeam(){if(state.teamRoster20261018)return;const norm=n=>n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();const roster=[
['seven-lucas-gargi','Lucas Gargi','Supervisor','Tropa dos Milhões',[]],
['seven-douglas','Douglas Carlos','Vendedor','Tropa dos Milhões',['Douglas']],
['seven-meire','Meire Silva','Vendedor','Tropa dos Milhões',['Meire']],
['seven-emanuel-vieira','Emanuel Vieira','Supervisor','Kingsman',[]],
['seven-luiz-borges','Luiz Borges','Vendedor','Kingsman',[]],
['seven-jonata-santana','Jonatã Santana','Supervisor','Seven Gold',[]],
['seven-atila-carvalho','Atila Carvalho','Vendedor','Seven Gold',['Átila Carvalho']],
['seven-israel-brito','Israel Brito','Vendedor','Seven Gold',[]],
['seven-josiele-martins','Josiele Martins','Vendedor','Seven Gold',[]],
['seven-lucas-araujo','Lucas Araújo','Vendedor','Seven Gold',[]],
['seven-victor-alves','Victor Alves','Vendedor','Seven Gold',[]]
];for(const [id,name,role,team,aliases] of roster){const p=state.people.find(p=>p.id===id)||state.people.find(p=>[name,...aliases].some(n=>norm(n)===norm(p.name)));if(p)Object.assign(p,{name,role,team});else state.people.push({id,name,role,team,pixType:'CPF',pix:''});}state.teamRoster20261018=true;}
syncScreenshotTeam();
migratePersonFares();
selected=state.people[0]?.id;
function validate(s){if(s?.version!==1||!Array.isArray(s.people)||!s.records||typeof s.records!=='object'||Array.isArray(s.records))throw Error('Backup inválido');const ids=new Set();for(const p of s.people){if(!p||typeof p.id!=='string'||!/^[\w-]+$/.test(p.id)||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||(p.fare!==undefined&&(!Number.isFinite(p.fare)||p.fare<0||p.fare>10000))||(p.fareGlobal!==undefined&&typeof p.fareGlobal!=='boolean'))throw Error('Pessoa inválida');ids.add(p.id);}for(const [k,r] of Object.entries(s.records)){if(!/^\d{4}-\d{2}:/.test(k)||!r||!Array.isArray(r.days)||!r.paid||!Array.isArray(r.sales)||r.sales.length!==3)throw Error('Registro inválido');for(const n of [r.fare,r.rides,r.commission,...r.sales])if(!Number.isFinite(n)||n<0||n>1e12)throw Error('Valor inválido');if(!Number.isInteger(r.rides)||r.rides<1||r.rides>20||r.days.some(d=>!Number.isInteger(d)||d<1||d>31)||new Set(r.days).size!==r.days.length)throw Error('Dias inválidos');if(r.transfers!==undefined){if(!Array.isArray(r.transfers))throw Error('Histórico inválido');const seen=new Set();for(const t of r.transfers){if(!t||typeof t.id!=='string'||!t.id||seen.has(t.id)||!Number.isInteger(t.week)||t.week<0||t.week>=weeks(k.slice(0,7)).length||!Number.isSafeInteger(t.amount)||t.amount<=0||t.amount>100000000000||!(validDate(t.date)||(t.date===null&&t.legacy===true))||typeof t.voided!=='boolean'||typeof t.note!=='string')throw Error('Pagamento inválido');seen.add(t.id);}}if(r.attendance){if(!r.costs||!r.payments||!Array.isArray(r.planned))throw Error('Saldo inválido');if(Object.values(r.attendance).some(v=>!['present','absent'].includes(v)))throw Error('Presença inválida');if([...Object.values(r.costs),...Object.values(r.payments)].some(v=>!Number.isSafeInteger(v)||v<0))throw Error('Pagamento inválido');if(r.planned.some(d=>!Number.isInteger(d)||d<1||d>31))throw Error('Escala inválida');}}validateAdvances(s);validateCompany(s);validateSales(s);return s;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='✓ Salvo neste navegador';return true;}catch{$('#save-status').textContent='Não foi possível salvar — exporte um backup';toast('Armazenamento indisponível. Exporte um backup.');return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function personFare(id=selected){const p=state.people.find(p=>p.id===id);if(!p)return 0;if(p.fareGlobal===true&&Number.isFinite(p.fare))return p.fare;const prior=Object.entries(state.records).filter(([key,r])=>key.endsWith(':'+id)&&Number.isFinite(r.fare)&&r.fare>0).sort(([a],[b])=>b.localeCompare(a))[0];if(prior){p.fare=prior[1].fare;p.fareGlobal=true;}else if(!Number.isFinite(p.fare))p.fare=0;return p.fare;}
function setPersonFare(id,fare){const p=state.people.find(p=>p.id===id);if(!p)return;p.fare=fare;p.fareGlobal=true;for(const [key,r] of Object.entries(state.records))if(key.endsWith(':'+id))r.fare=fare;}
function migratePersonFares(){for(const p of state.people){const fare=personFare(p.id);for(const [key,r] of Object.entries(state.records))if(key.endsWith(':'+p.id))r.fare=fare;}}
function record(id=selected){const key=$('#month').value+':'+id,r=state.records[key]??(state.records[key]={fare:personFare(id),rides:2,days:[],paid:{},sales:[0,0,0],commission:0,commissionPaid:false});r.fare=personFare(id);return r;}
function weeks(month=$('#month').value){const [y,m]=month.split('-').map(Number);const count=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7;return Array.from({length:Math.ceil((count+offset)/7)},(_,w)=>Array.from({length:7},(_,i)=>{const d=w*7+i-offset+1;return d>0&&d<=count?d:null;}));}
function selectedWeekIndex(month,monthWeeks){if(activeWeekMonth!==month){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),day=Number(today.slice(8));activeWeekMonth=month;activeWeekIndex=today.slice(0,7)===month?monthWeeks.findIndex(days=>days.includes(day)):0;}activeWeekIndex=Math.max(0,Math.min(monthWeeks.length-1,activeWeekIndex<0?0:activeWeekIndex));return activeWeekIndex;}
function prepare(r,month){if(!r.attendance){r.attendance={};r.costs={};r.payments={};r.planned=weeks(month).flatMap(ds=>ds.filter((d,i)=>d&&i<6));r.days.forEach(d=>{r.attendance[d]='present';r.costs[d]=cents(r.fare)*r.rides;});weeks(month).forEach((ds,i)=>{r.payments[i]=r.paid[i]?ds.filter(d=>r.days.includes(d)).length*cents(r.fare)*r.rides:0;});}if(!r.transfers){r.transfers=Object.entries(r.payments).filter(([,amount])=>amount>0).map(([week,amount])=>({id:'legacy-'+week,week:Number(week),amount,date:null,note:'Total registrado antes do histórico de pagamentos',legacy:true,voided:false}));}syncPayments(r);r.rides=DAILY_RIDES;r.planned=weeks(month).flatMap(ds=>ds.filter((d,i)=>d&&i<6));return r;}
function validDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date+'T12:00:00Z'))&&new Date(date+'T12:00:00Z').toISOString().slice(0,10)===date;}
function deleteTransfer(r,id){r.transfers=r.transfers.filter(t=>t.id!==id);syncPayments(r);}
function syncPayments(r){r.payments={};for(const t of r.transfers||[])if(!t.voided)r.payments[t.week]=(r.payments[t.week]||0)+t.amount;}
function transferList(r,i){const entries=r.transfers.filter(t=>t.week===i).sort((a,b)=>(a.date||'').localeCompare(b.date||''));return `<div class="payment-history"><div class="week-top"><h3>Pagamentos</h3><strong>${money((r.payments[i]||0)/100)}</strong></div>${entries.length?entries.map(t=>`<div class="transfer ${t.voided?'voided':''}"><div><strong>${t.date?esc(t.date.split('-').reverse().join('/')):'Data não informada'}</strong><small>${esc(t.note||'Pagamento de VT')}${t.voided?' · Cancelado':''}</small></div><div class="transfer-value"><strong>${money(t.amount/100)}</strong><div>${!t.voided?`<button data-edit-transfer="${esc(t.id)}" aria-label="Editar pagamento de ${t.date||'data não informada'}">Editar</button>`:''}<button data-delete-transfer="${esc(t.id)}">Excluir</button></div></div></div>`).join(''):'<p class="hint">Nenhum pagamento registrado nesta semana.</p>'}<button class="primary add-payment" data-add-transfer="${i}">＋ Registrar pagamento</button></div>`;}
function openTransfer(week,id=null){const r=prepare(record(),$('#month').value),t=r.transfers.find(t=>t.id===id);paymentContext={person:selected,month:$('#month').value,week,id};const form=$('#payment-form');form.reset();$('#payment-title').textContent=t?'Editar pagamento':'Registrar pagamento';$('#payment-reference').textContent=state.people.find(p=>p.id===selected).name+' · Semana '+(week+1)+' · '+$('#month').value.split('-').reverse().join('/');form.elements.date.value=t?(t.date||''):new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());form.elements.amount.value=t?formatCredit(t.amount):'';form.elements.note.value=t?t.note||'':'';$('#payment-dialog').showModal();}
$('#close-payment').onclick=()=>$('#payment-dialog').close();
$('#payment-form').onsubmit=e=>{e.preventDefault();const form=e.target;if(!form.reportValidity()||!paymentContext)return;const date=form.elements.date.value,amount=parseCredit(form.elements.amount.value);if(!validDate(date)||amount<=0||amount>100000000000){toast('Informe uma data válida e um valor maior que zero.');return;}const ctx=paymentContext,r=state.records[ctx.month+':'+ctx.person],prior=r.transfers.find(t=>t.id===ctx.id),entry={id:ctx.id||crypto.randomUUID(),week:ctx.week,amount,date,note:form.elements.note.value.trim(),legacy:false,voided:false};if(prior)Object.assign(prior,entry);else r.transfers.push(entry);delete r.vtResetEmpty;syncPayments(r);save();render();$('#payment-dialog').close();paymentContext=null;toast('Pagamento registrado');};
function weekLedger(r,ds,i,carry){if(r.vtResetEmpty)return {used:0,reserved:0,paid:0,carry,need:Math.max(0,-carry),end:carry};const daily=cents(r.fare)*DAILY_RIDES;let used=0,reserved=0;ds.filter(Boolean).forEach(d=>{if(r.attendance[d]==='present')used+=r.costs[d]??daily;else if(!r.attendance[d]&&r.planned.includes(d))reserved+=daily;});const paid=r.payments[i]||0;return {used,reserved,paid,carry,need:Math.max(0,used+reserved-carry-paid),end:carry+paid-used-reserved};}
function opening(id,month){let balance=0;Object.entries(state.records).filter(([k])=>k.endsWith(':'+id)&&k.slice(0,7)<month).sort(([a],[b])=>a.localeCompare(b)).forEach(([k,r])=>{prepare(r,k.slice(0,7));weeks(k.slice(0,7)).forEach((ds,i)=>{balance=weekLedger(r,ds,i,balance).end;});});return balance;}
function ledger(id=selected){const month=$('#month').value,r=prepare(record(id),month);let carry=opening(id,month);const rows=weeks().map((ds,i)=>{const row=weekLedger(r,ds,i,carry);carry=row.end;return row;});return {r,rows,opening:opening(id,month),end:carry};}
function vtView(r){const l=ledger(),month=$('#month').value,monthWeeks=weeks(month),i=selectedWeekIndex(month,monthWeeks),ds=monthWeeks[i],w=l.rows[i],valid=ds.filter(Boolean),today=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),isCurrent=month===today.slice(0,7)&&ds.includes(Number(today.slice(8))),monthLabel=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z'));return `<div class="configuration"><label>Valor de uma passagem (R$)<input type="text" inputmode="decimal" data-money autocomplete="off" data-money-min="0" data-money-max="10000" data-field="fare" value="${formatCredit(cents(r.fare))}"></label><label>Passagens por dia<input type="text" value="2 — ida e volta" readonly aria-readonly="true" class="locked-rides"></label><div class="daily">Valor por dia<strong>${money(cents(r.fare)*DAILY_RIDES/100)}</strong></div></div><div class="balance-summary"><div>Saldo trazido dos meses anteriores<strong>${money(l.opening/100)}</strong></div><div>Crédito livre após reservar dias previstos<strong>${money(Math.max(0,l.end)/100)}</strong></div></div><h3>Presenças e adiantamentos semanais</h3>${r.vtResetEmpty?'<p class="hint">Histórico zerado. As previsões deste mês voltam a ser calculadas ao registrar um novo pagamento ou marcar uma presença.</p>':''}<p class="hint">Clique no dia para alternar: sem marcação → veio → não veio → sem marcação. Segunda a sábado são dias previstos; domingo fica em cinza.</p><div class="week-carousel-head"><button type="button" data-week-shift="-1" ${i===0?'disabled':''} aria-label="Semana anterior">‹</button><div><span>Semana ${i+1} de ${monthWeeks.length}${isCurrent?' · Semana atual':''}</span><strong>${valid[0]} a ${valid.at(-1)} de ${monthLabel}</strong></div><button type="button" data-week-shift="1" ${i===monthWeeks.length-1?'disabled':''} aria-label="Próxima semana">›</button></div><div class="weeks week-carousel"><article class="week ${isCurrent?'current-week':''}"><div class="week-top"><h3>Semana ${i+1}</h3><small>${valid[0]} a ${valid.at(-1)}</small></div><div class="days">${ds.map((d,j)=>{const a=r.attendance[d],label=a==='present'?'Veio':a==='absent'?'Não veio':j<6?'Sem marcação · dia previsto':'Sem marcação · domingo';return `<button class="day ${a==='absent'?'absent':''} ${d&&!a?(j===6?'sunday':'expected'):''}" ${d?'data-day="'+d+'"':'disabled'} aria-label="${d?'Dia '+d+' · '+label:'Fora do mês'}" aria-pressed="${a==='present'}"><small>${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'][j]}</small><span>${d||'–'}${d?(a==='present'?' ✓':a==='absent'?' ×':''):''}</span></button>`;}).join('')}</div><dl class="ledger"><div><dt>Saldo anterior</dt><dd>${money(w.carry/100)}</dd></div><div><dt>VT utilizado (veio)</dt><dd>${money(w.used/100)}</dd></div><div><dt>Reservado (a confirmar)</dt><dd>${money(w.reserved/100)}</dd></div><div><dt>Falta adiantar</dt><dd>${money(w.need/100)}</dd></div><div><dt>${w.end>=0?'Saldo para a próxima semana':'VT ainda sem cobertura'}</dt><dd>${money(Math.abs(w.end)/100)}</dd></div></dl>${transferList(r,i)}</article></div>`;}
function render(){initAdvances();syncSales();$('#summary-section').hidden=mainView!=='summary';$('#summary-nav').className=mainView==='summary'?'selected':'';$('#sales-section').hidden=mainView!=='sales';$('#sales-nav').className=mainView==='sales'?'selected':'';$('#team-section').hidden=mainView!=='team';$('#company-section').hidden=mainView!=='company';$('#team-nav').className=mainView==='team'?'selected':'';$('#company-nav').className=mainView==='company'?'selected':'';if(mainView==='summary'){renderSummary();return;}if(mainView==='company'){renderCompany();return;}if(mainView==='sales'){renderSales();return;}let vt=0,comm=0,paid=0,pending=0;state.people.forEach(p=>{const l=ledger(p.id),r=l.r;vt+=l.rows.reduce((n,w)=>n+w.used,0)/100;const cs=commissionSummary(p.id);comm+=cs.net/100;paid+=l.rows.reduce((n,w)=>n+w.paid,0)/100+(cs.paid/100);pending+=Math.max(0,-l.end)/100+(cs.remaining/100);});$('#stats').innerHTML=[['Total utilizado no mês',vt+comm,'VT de presenças + comissões líquidas'],['Vale-transporte utilizado',vt,'Somente dias confirmados: veio'],['Comissões líquidas',comm,'Após vales e adiantamentos'],['Ainda a pagar / adiantar',pending,'Pago para este mês: '+money(paid)]].map(([label,value,note])=>`<div class="stat"><span class="stat-label">${label}</span><strong>${money(value)}</strong><small>${note}</small></div>`).join('');const currentPerson=state.people.find(p=>p.id===selected);$('#people').className='people person-picker';$('#people').innerHTML=`<div class="person-picker-field"><span class="person-picker-label">Selecionar funcionário</span><div class="person-combobox"><button type="button" id="team-person-toggle" aria-haspopup="listbox" aria-expanded="false"><span class="avatar">${esc(currentPerson?.name.slice(0,2).toUpperCase()||'—')}</span><span class="person-current"><strong>${esc(currentPerson?.name||'Nenhum funcionário')}</strong><small>${esc(currentPerson?.role||'')}${currentPerson?.team?' · '+esc(currentPerson.team):''}</small></span><span class="person-chevron" aria-hidden="true">⌄</span></button><div class="person-picker-menu" id="team-person-menu" hidden><div class="person-picker-search"><span aria-hidden="true">⌕</span><input id="team-person-filter" type="search" autocomplete="off" placeholder="Pesquisar funcionário..." aria-label="Pesquisar funcionário"></div><div class="person-picker-options" role="listbox">${state.people.map(p=>`<button type="button" role="option" data-person-picker="${esc(p.id)}" data-person-search="${esc((p.name+' '+(p.role||'')+' '+(p.team||'')).toLocaleLowerCase('pt-BR'))}" aria-selected="${p.id===selected}"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.role||'Prestador PJ')}${p.team?' · '+esc(p.team):''}</small></span>${p.id===selected?'<span class="person-check">✓</span>':''}</button>`).join('')}</div></div></div></div>`;
const p=state.people.find(p=>p.id===selected);if(!p){$('#detail').innerHTML='<div class="empty"><div class="empty-icon">♧</div><h2>O primeiro passo é a sua equipe</h2><p>Cadastre uma pessoa para organizar o vale-transporte<br>e acompanhar as comissões de cada mês.</p><button class="primary" data-new>＋ Cadastrar primeira pessoa</button></div>';return;}
const r=record();$('#detail').innerHTML=`<div class="profile"><div class="identity"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(p.name)}<span class="badge">PJ</span></h3><small>${esc(p.role||'Prestador PJ')}${p.team?' · '+esc(p.team):''}</small><small>Pix · ${esc(p.pixType||'CPF')}: ${esc(p.pix||'Não cadastrado')}</small></div></div><div class="tabs profile-tabs"><button data-tab="vt" class="${tab==='vt'?'selected':''}">Vale-transporte</button><button data-tab="commission" class="${tab==='commission'?'selected':''}">Vendas e comissão</button><button data-tab="advances" class="${tab==='advances'?'selected':''}">Vales e adiantamentos</button></div><button id="edit">Editar cadastro</button></div>`+(tab==='vt'?vtView(r):tab==='advances'?advancesView():personSalesView());}
function openPerson(edit=false){editing=edit?selected:null;$('#person-form').reset();$('#dialog-title').textContent=edit?'Editar pessoa':'Adicionar pessoa';if(edit){const p=state.people.find(x=>x.id===selected);for(const k of ['name','role','commissionRole','team','pixType','pix'])$('#person-form').elements[k].value=p[k]||'';}$('#person-dialog').showModal();}
$('#add').onclick=()=>openPerson();$('#close-dialog').onclick=()=>$('#person-dialog').close();$('#person-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;const p={...(editing?state.people.find(x=>x.id===editing):{}),id:editing||crypto.randomUUID(),name,role:f.get('role').trim(),commissionRole:f.get('commissionRole'),team:f.get('team').trim(),pixType:f.get('pixType'),pix:f.get('pix').trim()};if(editing)state.people[state.people.findIndex(x=>x.id===editing)]=p;else state.people.push(p);selected=p.id;save();render();$('#person-dialog').close();toast('Cadastro salvo');};
$('#month').onchange=()=>{if(!/^\d{4}-\d{2}$/.test($('#month').value))$('#month').value=initialMonth;render();};function shift(n){const [y,m]=$('#month').value.split('-').map(Number);const d=new Date(y,m-1+n,1);$('#month').value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();}$('#prev').onclick=()=>shift(-1);$('#next').onclick=()=>shift(1);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.person){selected=b.dataset.person;render();}if(b.hasAttribute('data-new'))openPerson();if(b.id==='edit')openPerson(true);if(b.dataset.tab){tab=b.dataset.tab;render();}if(b.dataset.weekShift){activeWeekIndex+=Number(b.dataset.weekShift);render();}if(b.dataset.day){const r=prepare(record(),$('#month').value),d=Number(b.dataset.day),a=r.attendance[d];delete r.vtResetEmpty;if(!a){r.attendance[d]='present';r.costs[d]=cents(r.fare)*DAILY_RIDES;}else if(a==='present'){r.attendance[d]='absent';delete r.costs[d];}else{delete r.attendance[d];delete r.costs[d];}r.days=Object.keys(r.attendance).filter(k=>r.attendance[k]==='present').map(Number);save();render();}if(b.hasAttribute('data-add-transfer'))openTransfer(Number(b.dataset.addTransfer));if(b.dataset.editTransfer){const t=record().transfers.find(t=>t.id===b.dataset.editTransfer);if(t)openTransfer(t.week,t.id);}if(b.dataset.deleteTransfer){const r=record(),t=r.transfers.find(t=>t.id===b.dataset.deleteTransfer);if(t&&confirm('Excluir definitivamente este pagamento de '+money(t.amount/100)+'? O lançamento será removido e o saldo recalculado. Não será possível restaurá-lo pelo sistema.')){deleteTransfer(r,t.id);save();render();toast('Pagamento excluído definitivamente');}}if(b.id==='commission-pay')settleCommission();});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.field!=='fare')return;if(!t.checkValidity()||t.value===''){t.reportValidity();render();return;}setPersonFare(selected,parseCredit(t.value)/100);save();render();});
document.addEventListener('click',e=>{const toggle=e.target.closest('#team-person-toggle'),option=e.target.closest('[data-person-picker]'),combo=e.target.closest('.person-combobox'),menu=$('#team-person-menu');if(toggle&&menu){const open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)setTimeout(()=>$('#team-person-filter')?.focus(),0);return;}if(option){selected=option.dataset.personPicker;render();return;}if(!combo&&menu){menu.hidden=true;$('#team-person-toggle')?.setAttribute('aria-expanded','false');}});
document.addEventListener('input',e=>{if(e.target.id!=='team-person-filter')return;const query=e.target.value.trim().toLocaleLowerCase('pt-BR');document.querySelectorAll('[data-person-picker]').forEach(option=>option.hidden=query&&!option.dataset.personSearch.includes(query));});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const menu=$('#team-person-menu');if(menu&&!menu.hidden){menu.hidden=true;const toggle=$('#team-person-toggle');toggle?.setAttribute('aria-expanded','false');toggle?.focus();}});
function resetAllVT(){state.people.forEach(p=>record(p.id));for(const r of Object.values(state.records)){Object.assign(r,{days:[],paid:{},attendance:{},costs:{},payments:{},transfers:[],planned:[],vtResetEmpty:true});}paymentContext=null;}
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='seven-gold-backup-'+$('#month').value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onclick=()=>$('#backup').click();$('#backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=validate(JSON.parse(await file.text()));if(confirm('Substituir os dados deste navegador pelo backup selecionado? Exporte o backup atual antes de continuar.')){state=data;selected=state.people[0]?.id;save();render();toast('Backup importado');}}catch{toast('Backup inválido. Nenhum dado foi alterado.');}e.target.value='';};render();save();

function renderTeamFinancialStats(){let vtPaid=0,vtPending=0,commissionPaid=0,commissionPending=0;state.people.forEach(person=>{const l=ledger(person.id),cs=commissionSummary(person.id);vtPaid+=l.rows.reduce((total,week)=>total+week.paid,0);vtPending+=Math.max(0,-l.end);commissionPaid+=cs.paid;commissionPending+=cs.remaining;});const vtTotal=vtPaid+vtPending,commissionTotal=commissionPaid+commissionPending,total=vtTotal+commissionTotal,totalPaid=vtPaid+commissionPaid,totalPending=vtPending+commissionPending,card=(label,value,paid,pending,tone='')=>`<div class="stat team-finance-stat ${tone}"><span class="stat-label">${label}</span><strong>${money(value/100)}</strong><div class="team-stat-breakdown"><span>Já pago<b>${money(paid/100)}</b></span><span>Falta pagar<b>${money(pending/100)}</b></span></div></div>`;$('#stats').innerHTML=card('Total de gastos do mês',total,totalPaid,totalPending,'total')+card('Vale-transporte do mês',vtTotal,vtPaid,vtPending)+card('Comissões do mês',commissionTotal,commissionPaid,commissionPending);}
const renderWithTeamFinancialStats=render;render=function(){renderWithTeamFinancialStats();if(mainView==='team')renderTeamFinancialStats();};


function setupSidebarLayout(){
  const sidebar=document.querySelector('aside'),pageHeader=document.querySelector('main>header'),tabs=document.querySelector('main>.main-tabs'),toolbar=document.querySelector('main>.toolbar');
  if(!sidebar||!pageHeader||!tabs||!toolbar)return;
  const controls=document.createElement('div');controls.className='sidebar-controls';controls.append(pageHeader,tabs,toolbar);sidebar.querySelector('.brand').after(controls);
  const toggle=document.createElement('button');toggle.className='mobile-menu-toggle';toggle.type='button';toggle.setAttribute('aria-label','Abrir menu');toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<span></span><span></span><span></span>';
  const backdrop=document.createElement('button');backdrop.className='sidebar-backdrop';backdrop.type='button';backdrop.setAttribute('aria-label','Fechar menu');document.body.prepend(backdrop,toggle);
  const closeMenu=()=>{document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu');};
  toggle.onclick=()=>{const open=document.body.classList.toggle('menu-open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');};
  backdrop.onclick=closeMenu;
  tabs.addEventListener('click',event=>{if(event.target.closest('button'))closeMenu();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
}

if(typeof window!=='undefined'){
  setupSidebarLayout();
  const sdk=document.createElement('script');
  sdk.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
  sdk.onload=()=>{const integration=document.createElement('script');integration.src='cloud.js?v=global-fare-20261030';document.body.append(integration);};
  sdk.onerror=()=>{const status=document.querySelector('#save-status');if(status)status.textContent='Dados locais · conexão on-line indisponível';};
  document.head.append(sdk);
}
